from pysat.formula import CNF
from pysat.solvers import Solver

# Define the Sudoku grid size and block size
n = 9
block_size = 3

# Create a CNF formula
formula = CNF()

# Add clauses for each row, column, and block
for i in range(n):
    for j in range(n):
        # Each cell must contain at least one number
        formula.append([n * n * i + n * j + k for k in range(n)])
        # Each cell can contain at most one number
        for k in range(n):
            for k2 in range(k + 1, n):
                formula.append([-n * n * i - n * j - k, -n * n * i - n * j - k2])

# Add clauses for each row
for i in range(n):
    for k in range(n):
        # Each row must contain each number exactly once
        formula.append([n * n * i + n * j + k for j in range(n)])
        for j in range(n):
            for j2 in range(j + 1, n):
                formula.append([-n * n * i - n * j - k, -n * n * i - n * j2 - k])

# Add clauses for each column
for j in range(n):
    for k in range(n):
        # Each column must contain each number exactly once
        formula.append([n * n * i + n * j + k for i in range(n)])
        for i in range(n):
            for i2 in range(i + 1, n):
                formula.append([-n * n * i - n * j - k, -n * n * i2 - n * j - k])

# Add clauses for each block
for i in range(0, n, block_size):
    for j in range(0, n, block_size):
        for k in range(n):
            # Each block must contain each number exactly once
            formula.append([n * n * (i + i2) + n * (j + j2) + k for i2 in range(block_size) for j2 in range(block_size)])
            for i2 in range(block_size):
                for j2 in range(block_size):
                    for i3 in range(block_size):
                        for j3 in range(block_size):
                            if (i2, j2) != (i3, j3):
                                formula.append([-n * n * (i + i2) - n * (j + j2) - k, -n * n * (i + i3) - n * (j + j3) - k])

# Add clauses for the fixed values
fixed_values = {2: 3, 11: 6, 13: 8, 20: 9, 22: 2, 35: 7, 42: 2, 46: 9, 50: 4, 57: 6, 58: 4, 60: 9, 62: 8, 69: 5, 78: 6, 79: 4}
for index, value in fixed_values.items():
    formula.append([n * n * (index // n) + n * (index % n) + value - 1])

# Solve the formula
solver = Solver(bootstrap_with=formula.clauses)
if solver.solve():
    model = solver.get_model()
    solution = [0] * n * n
    for lit in model:
        if lit > 0:
            solution[(lit - 1) // n] = (lit - 1) % n + 1
    print(solution)
else:
    print("UNSATISFIABLE")
